import { Flex, Text } from "@chakra-ui/react";
import type { Node } from "reactflow";
import { extractNodeLabel } from "../../utils";
import { Icon as NodeIcon } from "./Icon";
import { type FlowNode, FlowNodeType } from "../../types";

interface Props {
  node: Node<FlowNode>;
}

export const Content = ({ node }: Props) => {
  const { data } = node;
  const containerSx = {
    flexGrow: 1,
    px: "2",
    py: "1.5",
    alignItems: "center",
    justifyContent: "flex-start",
    width: "100%",
    position: "relative",
    minWidth: data.type !== FlowNodeType.Logic ? "12.25rem" : undefined, // matches DEFAULT_NODE_WIDTH
  };

  const textSx = {
    ml: "2",
    wordBreak: "break-word",
    display: "-webkit-box",
    "-webkit-line-clamp": "2",
    "-webkit-box-orient": "vertical",
    overflow: "hidden",
  };

  return (
    <Flex css={containerSx}>
      <NodeIcon node={data} />
      <Text textStyle="xs" css={textSx}>
        {extractNodeLabel(data)}
      </Text>
    </Flex>
  );
};
